        if (next == null || !claims.changeStatus(sheet, claim.id(), claim.status(), next)) {
            throw new InvalidClaimStatusChangeException(
                    "A " + claim.status() + " claim does not allow " + requested.name().toLowerCase());
        }
        // Opening gives the sheet's next number, or, while the sheet numbers by period from on or before its today,
        // the next number in the claim's period (X for none); a voided claim keeps the number it had (never reused).
        Claim changed = claim;
        if (requested == ClaimStatusChange.OPEN) {
            changed = number(sheet, claim);
            claims.setOpenedBy(sheet, claim.id(), user);
        }
        String fields = changed.statusAuditFields(person.name());
        // Settling (or approving a PENDING claim, its live figure then) fixes the due at the person's grade rate in force on the claim's date (or the figure its
        // statement bound), with its late charge frozen in; with no rate there is nothing to fix, so it stays live.
        if (requested == ClaimStatusChange.SETTLE || requested == ClaimStatusChange.APPROVE) {
            BigDecimal due = claim.due(rates.list(sheet), person.gradeOn(claim.date()), settings.floor(sheet),
                    settings.late(sheet, clock.today(sheet)));
            claims.setSettledDue(sheet, claim.id(), due);
            fields += " due=" + (due == null ? "n/a" : due.toPlainString());
        }
        if (requested == ClaimStatusChange.REJECT) {
            fields += " reason=" + reason.trim();
        }
        log.record(sheet, user, claim.id());
        audit.record(requested.event() + " sheet=" + sheet + " by=" + user + " " + fields);
        rollup.record(sheet, user, before);
    }

    /**
     * Gives an opening claim the sheet's next number, or, while the sheet numbers by period from on or before its
     * today, the next number in the claim's period (X for none); returns the claim so numbered.
     */
    public Claim number(String sheet, Claim claim) {
        LocalDate from = settings.periodNumberingFrom(sheet);
        if (from != null && !clock.today(sheet).isBefore(from)) {
            String period = periods.nameOn(sheet, LocalDate.parse(claim.date()));
            String key = period == null ? "" : period;
            Claim numbered = claim.withPeriodNumber((period == null ? "X" : period) + "-" + claims.nextPeriodNumber(sheet, key));
            claims.setPeriodNumber(sheet, claim.id(), numbered.periodNumber());
            return numbered;
        }
        Claim numbered = claim.withNumber(claims.nextNumber(sheet));
        claims.setNumber(sheet, claim.id(), numbered.number());
        return numbered;
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.period.Periods;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.Roles;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.SheetClock;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/**
 * A steward re-settles a SETTLED claim outside a closed period: its due is fixed again at the figure it would have
 * today as an OPEN claim bound by no statement (today's rates, grades, floor and late charge), and its status log
 * gains a SETTLED line.
 */
public class ResettleClaim {
    public void resettle(@PathVariable("sheet") String sheet, @RequestParam("user") String user, @Val Claim claim,
            Claims claims, People people, Rates rates, Periods periods, Roles roles, Settings settings,
            SheetClock clock, Audit audit, Rollup rollup, ClaimLog log) throws InvalidClaimStatusChangeException {
        if (!Role.STEWARD.equals(roles.of(sheet, user))) {
            throw new InvalidClaimStatusChangeException("Only a steward re-settles a claim");
        }
        if (claim.status() != ClaimStatus.SETTLED) {
            throw new InvalidClaimStatusChangeException("A " + claim.status() + " claim cannot be re-settled");
        }
        if (periods.closedOn(sheet, LocalDate.parse(claim.date()))) {
            throw new InvalidClaimStatusChangeException("A claim dated inside a closed period cannot be re-settled");
        }
        Person person = people.find(sheet, claim.person());
        BigDecimal was = claim.settledDue() == null ? null : new BigDecimal(claim.settledDue());
        BigDecimal due = claim.asOpenUnbound().due(rates.list(sheet), person.gradeOn(claim.date()),
                settings.floor(sheet), settings.late(sheet, clock.today(sheet)));
        Rollup.Snapshot before = rollup.take(sheet);
        if (!claims.resettle(sheet, claim.id(), was, due)) {
            throw new InvalidClaimStatusChangeException("The claim changed since it was read");
        }
        log.record(sheet, user, claim.id());
        audit.record("CLAIM_RESETTLED sheet=" + sheet + " by=" + user + " " + claim.statusAuditFields(person.name())
                + " old=" + (was == null ? "n/a" : was.toPlainString())
                + " new=" + (due == null ? "n/a" : due.toPlainString()));
        rollup.record(sheet, user, before);
    }
}
package net.officefloor.hq.app.claim;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestParam;

/**
 * Settles each selected claim in list order (people in the order they were added, newest claim first within a
 * person) by the rules of settling one claim, as the signed-in user; one a clerk's settle sends to PENDING counts as
 * settled, one that cannot be settled is left as it is and counted refused.
 */
public class BulkSettleClaims {
    public void settle(@PathVariable("sheet") String sheet, @RequestParam("user") String user,
            @RequestBody BulkSettleRequest request, Claims claims, People people, ClaimStatusChanger changer,
            ObjectResponse<BulkSettleResponse> response) {
        Map<Long, Integer> personOrder = new HashMap<>();
        for (Person person : people.list(sheet)) {
            personOrder.put(person.id(), personOrder.size());
        }
        List<Claim> selected = new ArrayList<>();
        int refused = 0;
        for (Long id : new LinkedHashSet<>(request == null || request.claims() == null ? List.of() : request.claims())) {
            Claim claim = id == null ? null : claims.find(sheet, id);
            if (claim == null) {
                refused++;
            } else {
                selected.add(claim);
            }
        }
        selected.sort(Comparator.comparing((Claim c) -> personOrder.getOrDefault(c.person(), Integer.MAX_VALUE))
                .thenComparing(Claim::id, Comparator.reverseOrder()));
        int settled = 0;
        for (Claim claim : selected) {
            try {
                // Re-read so each claim is settled as the store holds it after the ones before it.
                changer.change(sheet, user, claims.find(sheet, claim.id()), ClaimStatusChange.SETTLE);
                settled++;
            } catch (InvalidClaimStatusChangeException refusal) {
                refused++;
            }
        }
        response.send(new BulkSettleResponse(settled, refused, claims.list(sheet)));
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.sql.Date;
