import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { byUser } from '../session/session';
import { PersonColumnHeaders, PersonColumns } from '../../slots/defs/personRow';
import { peoplePath, usePeople } from '../people/people';
import type { Person } from '../people/people';
import { personDueCents, useClaims, useLate } from '../claims/claims';
import { twoDecimals, useRates } from '../rates/rates';
import { useCapCents, useFloorCents } from '../settings/settings';
import { useSheetToday } from '../sheet/sheet';
import { patronsKey, usePatrons } from './patrons';
import type { Patron } from './patrons';

function PatronsHeader() {
  return (
    <>
      <th>Patrons</th>
      <th>Backing</th>
      <th />
    </>
  );
}

// A person's patrons (names sorted, comma separated) and their backing: the patrons' due-totals added up,
// skipping those that are n/a. A patron is picked from the others on the sheet and named one at a time; the
// server refuses a patron already named.
function PersonPatrons({ sheet, user, person }: { sheet: string; user: string; person: Person }) {
  const queryClient = useQueryClient();
  const { data: everyone = [] } = usePeople(sheet);
  const { data: patrons = [] } = usePatrons(sheet);
  const { data: claims = [] } = useClaims(sheet);
  const { data: rates = [] } = useRates(sheet);
  const today = useSheetToday(sheet);
  const floor = useFloorCents(sheet);
  const cap = useCapCents(sheet);
  const late = useLate(sheet);
  const [picked, setPicked] = useState('');

  const mine = patrons
    .filter((p) => p.person === person.id)
    .map((p) => everyone.find((e) => e.id === p.patron))
    .filter((p): p is Person => p !== undefined);
  const names = mine.map((p) => p.name).sort((a, b) => a.localeCompare(b));
  const backing = mine.reduce((sum, p) => sum + (personDueCents(claims, rates, p, today, floor, late, cap) ?? 0n), 0n);
  const others = everyone.filter((p) => p.id !== person.id);

  const add = useMutation({
    mutationFn: (patron: number) =>
      postJson<Patron[]>(byUser(`${peoplePath(sheet)}/${person.id}/patrons`, user), { patron }),
    onSuccess: (updated) => {
      queryClient.setQueryData(patronsKey(sheet), updated);
      setPicked('');
    },
  });
  const send = useSubmitOnce(add);

  return (
    <>
      <td data-testid="person-patrons">{names.join(', ')}</td>
      <td data-testid="person-backing">{twoDecimals(backing)}</td>
      <td>
        <select
          data-testid="person-patron-select"
          value={picked}
          onChange={(e) => {
            setPicked(e.target.value);
            add.reset();
          }}
        >
          <option value="">Patron…</option>
          {others.map((p) => (
            <option key={p.id} value={String(p.id)}>
              {p.name}
            </option>
          ))}
        </select>{' '}
        <button
          type="button"
          data-testid="person-patron-add"
          disabled={add.isPending}
          onClick={() => send(picked === '' ? -1 : Number(picked))}
        >
          Add patron
        </button>
        {add.isError && (
          <span data-testid="person-patron-error" role="alert">
            {' '}A patron must be someone else on the sheet, not already named.
          </span>
        )}
      </td>
    </>
  );
}

export const contributions = [
  PersonColumnHeaders.fill({ order: 50, Component: PatronsHeader }),
  PersonColumns.fill({ order: 50, Component: PersonPatrons }),
];
import type { ComponentType } from 'react';

// The contribution store. It imports NOTHING — that is deliberate: discovery (slots/discover.ts)
// pulls in every feature's contribution file, and those files reach a slot definition, which
// reaches defineSlot, which reaches this file. Keeping the arrows one-way (discover -> features ->
// defs -> Slot -> registry) is what stops the module graph forming a cycle.

export type Registered = {
  slot: string;
  order: number;
  /** Source file — the React key and the deterministic tie-break for equal `order`. */
  from: string;
  Component: ComponentType<never>;
};

const contributions: Registered[] = [];

/** Called once per contribution at startup, by slots/discover.ts. */
export function register(entry: Registered): void {
  contributions.push(entry);
}

export function forSlot(id: string): Registered[] {
  return contributions
    .filter((c) => c.slot === id)
    .sort((a, b) => a.order - b.order || a.from.localeCompare(b.from));
}
import { Fragment, createElement } from 'react';
import type { ComponentType, ReactElement } from 'react';
import { forSlot } from './registry';

// ── Slots: regions of the UI that features fill ───────────────────────────────────────────────
// A SLOT is a region of the UI that features fill. Whatever renders a region does not list what
// goes in it; a contribution to a region (a panel, a table column, a row action, a toolbar
// control, a nav link) is a separate file, registered by discovery (slots/discover.ts).
//
//   1. declare a region  ->  slots/defs/projectDetail.ts
//        export const ProjectDetail = defineSlot<{ projectId: number }>('project.detail');
//   2. render it         ->  <ProjectDetail.Slot projectId={id} />
//   3. fill it           ->  features/projects/notes.slot.tsx
//        export const contribution = ProjectDetail.fill({ order: 30, Component: ProjectNotes });
//
// This file, slots/registry.ts and slots/discover.ts implement that mechanism; a region is
// declared by a file under slots/defs/.

export type Contribution<Ctx> = {
  /** Lower renders first; equal orders fall back to file path, so the order is always stable. */
  order?: number;
  Component: ComponentType<Ctx>;
};

export type SlotDef<Ctx extends object> = {
  id: string;
  /** Renders the region. Its props ARE the context handed to every contribution. */
  Slot: (ctx: Ctx) => ReactElement;
  /** A feature wraps its contribution in this, to be typed against the region's context. */
  fill: (contribution: Contribution<Ctx>) => Contribution<Ctx> & { slot: string };
};

export function defineSlot<Ctx extends object = Record<string, never>>(id: string): SlotDef<Ctx> {
  return {
    id,
    // A Fragment, never a wrapper element: a slot must be usable inside <thead>/<tr> (columns and
    // row actions are slots too), where a stray <div> would be invalid markup.
    Slot: (ctx: Ctx) =>
      createElement(
        Fragment,
        null,
        forSlot(id).map((c) =>
          createElement(c.Component as ComponentType<Ctx>, { key: c.from, ...ctx }),
        ),
      ),
    fill: (contribution) => ({ slot: id, ...contribution }),
  };
}
