import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

/** That `patron` is one of `person`'s patrons: both are ids of people on the sheet. */
export type Patron = { person: number; patron: number };

export const patronsKey = (sheet: string) => ['patrons', sheet] as const;

export const patronsPath = (sheet: string) => `/api/sheets/${encodeURIComponent(sheet)}/patrons`;

/** Every patron named on the sheet. */
export function usePatrons(sheet: string) {
  return useQuery({
    queryKey: patronsKey(sheet),
    queryFn: () => getJson<Patron[]>(patronsPath(sheet)),
  });
}
import { asString, useSearchParam } from '../../url/useSearchParam';

// Who is signed in and which sheet is active. Both live in the URL (search params `user` and
// `sheet`), so any feature reads them directly.
export const useCurrentUser = () => useSearchParam('user', asString);
export const useCurrentSheet = () => useSearchParam('sheet', asString);

/** A write's path carrying who made it, so the server can record it in the audit file. */
export const byUser = (path: string, user: string) => `${path}?user=${encodeURIComponent(user)}`;
// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data.
/** A non-2xx answer; `status` lets a form tell one refusal from another. */
export class HttpError extends Error {
  constructor(message: string, readonly status: number) {
    super(message);
  }
}

async function send<T>(path: string, init?: RequestInit): Promise<T> {
  const res = await fetch(path, init);
  if (!res.ok) {
    throw new HttpError(`${init?.method ?? 'GET'} ${path} -> ${res.status}`, res.status);
  }
  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
}

export function getJson<T>(path: string): Promise<T> {
  return send<T>(path);
}

export function postJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}

export function putJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}
